      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave researchers a powerful framework for understanding strongly correlated electrons and has become central to modern condensed-matter physics.",
        "attribution": "Georges, Vollhardt, and Kotliar are leading architects of the method and its influential applications; the broader development involved a substantial research community.",
        "maturity": "The framework has been used and developed for decades, with extensive theoretical and computational validation.",
        "uncertainties": [
          "The long-term reach of the method is clear, but dividing credit among its originators and subsequent developers is difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed a tunable route to correlated and superconducting states, opening a major new direction in quantum-materials research.",
        "attribution": "Bistritzer and MacDonald established the theoretical mechanism for flat bands; Jarillo-Herrero's group demonstrated the striking correlated behavior experimentally.",
        "maturity": "The phenomenon has been intensively reproduced and extended across moiré systems, though the field is still evolving.",
        "uncertainties": [
          "The microscopic origins and relation among the different observed phases remain under active study."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals established control of light through periodic structures, enabling important advances in optical physics and device design.",
        "attribution": "Yablonovitch and John independently developed the central concept, while Joannopoulos made major contributions to its theoretical understanding and development.",
        "maturity": "The underlying physics is well established and has supported decades of research and practical photonic applications.",
        "uncertainties": [
          "The independent origins and broad community contributions make a three-person attribution challenging."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Gwendal Fève",
        "Michael J. Manfra",
        "Moty Heiblum"
      ],
      "assessment": {
        "nobel_worthiness": "Measurements of fractional charge and anyonic statistics in quantum Hall systems probe foundational properties of topological matter and fractionalization.",
        "attribution": "These researchers made important experimental contributions to detecting and characterizing fractionalized excitations; the underlying quantum Hall discoveries and many experiments involved others.",
        "maturity": "Fractional charge is well supported, while experimental claims about statistics have advanced through increasingly precise but technically demanding measurements.",
        "uncertainties": [
          "The case depends on which measurements are considered decisive for demonstrating statistics and how credit is allocated across experiments."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Akira Ohtomo",
        "Harold Y. Hwang",
        "Jochen Mannhart"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of a two-dimensional electron gas at oxide interfaces showed that interfaces can host electronic states and behaviors absent in the bulk materials.",
        "attribution": "Ohtomo and Hwang reported the landmark interface result; Mannhart helped establish and develop the broader field of oxide heterostructures.",
        "maturity": "The result motivated extensive experimental and theoretical work, although individual interface phases and proposed mechanisms vary in robustness.",
        "uncertainties": [
          "The breadth of phenomena grouped under oxide interfaces makes it hard to define one discovery and its boundaries."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Roland Wiesendanger",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions are stable, topologically structured spin textures that have reshaped research in magnetism and opened promising routes for spin-based devices.",
        "attribution": "Pfleiderer, Wiesendanger, and Tokura made major contributions to observing, imaging, and developing skyrmion physics in distinct material settings.",
        "maturity": "Skyrmions are firmly established in several systems, while reliable device use and some proposed dynamical advantages remain under development.",
        "uncertainties": [
          "The discovery and development span theory, materials, and imaging, with significant contributions beyond these three researchers."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "Atomic-resolution qPlus force microscopy made it possible to probe local forces and resolve chemical structure at surfaces with exceptional precision.",
        "attribution": "Giessibl developed the qPlus sensor approach, and Meyer and Gross contributed substantially to its refinement and landmark applications.",
        "maturity": "The technique is well established and has enabled many reproducible measurements in surface science.",
        "uncertainties": [
          "The case is stronger as a major enabling instrument than as a single fundamental discovery, and instrument development has broad contributors."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices created a clean, controllable platform for simulating quantum many-body systems and observing phenomena that are difficult to access in solids.",
        "attribution": "Bloch and Greiner led landmark experiments, while Zoller provided foundational theory for quantum simulation with trapped atoms.",
        "maturity": "The platform has been validated across many experiments and continues to produce new results; some applications as a quantitative simulator are still developing.",
        "uncertainties": [
          "The field has many important experimental and theoretical contributors, and its eventual impact on understanding real materials is not yet settled."
        ]
      }
    }
  ]
